package com.johnny.hotel;
import com.johnny.hotel.ar.*;import com.johnny.hotel.ar.ArModels.*;import com.johnny.hotel.businessdate.*;import com.johnny.hotel.entity.*;import com.johnny.hotel.mapper.*;import com.johnny.hotel.pagination.*;import com.johnny.hotel.payment.*;import com.johnny.hotel.service.*;import org.junit.jupiter.api.*;import java.math.*;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.*;import static org.mockito.Mockito.*;
class ArServiceTest {ArMapper db;ArAccess access;FolioMapper folios;FolioFinancialService financial;BusinessDateService dates;PaymentCoreMapper tx;SysAuditLogMapper audits;ArService service;Clock clock=Clock.fixed(Instant.parse("2026-09-23T02:00:00Z"),ZoneId.of("Asia/Shanghai"));
 @BeforeEach void init(){db=mock(ArMapper.class);access=mock(ArAccess.class);folios=mock(FolioMapper.class);financial=mock(FolioFinancialService.class);dates=mock(BusinessDateService.class);tx=mock(PaymentCoreMapper.class);audits=mock(SysAuditLogMapper.class);var p=new PaginationProperties();p.setMaxPageSize(100);p.setBrowseLimit(100);service=new ArService(db,access,folios,financial,dates,tx,audits,new PaginationSupport(p),clock);when(access.actor()).thenReturn(new ArAccess.Actor(7L,Set.of("FINANCE")));when(db.lockRequest(anyString())).thenAnswer(i->i.getArgument(0));when(dates.postingDate()).thenReturn(LocalDate.of(2026,9,23));when(db.insert(any())).thenAnswer(i->{((ArLedgerEntry)i.getArgument(0)).setId(99L);return 1;});when(audits.insert(any())).thenReturn(1);when(tx.insertTransaction(any())).thenReturn(1);}
 @Test void directBillSettlesFolioWithoutCashOrRevenue(){var account=ArAccount.builder().id(2L).status("ACTIVE").currency("CNY").creditLimit(new BigDecimal("2000.00")).build();var folio=Folio.builder().id(3L).currency("CNY").balanceAmount(new BigDecimal("1200.00")).build();when(folios.selectByIdForUpdate(3L)).thenReturn(folio);when(db.lockAccount(2L)).thenReturn(account);when(db.outstanding(2L)).thenReturn(BigDecimal.ZERO);when(financial.recalculateSummary(3L)).thenReturn(folio,Folio.builder().id(3L).balanceAmount(BigDecimal.ZERO).build());var e=service.transfer(2L,3L,TransferRequest.builder().amount(new BigDecimal("1200.00")).requestKey("ar-transfer-1").build());assertEquals("FOLIO_TRANSFER",e.getEntryType());verify(financial,times(2)).recalculateSummary(3L);verifyNoInteractions(tx);}
 @Test void realArPaymentCreatesExactlyOneExternalInAndRetryIsIdempotent(){var account=ArAccount.builder().id(2L).currency("CNY").build();when(db.lockAccount(2L)).thenReturn(account);when(db.outstanding(2L)).thenReturn(new BigDecimal("1200.00"));var request=PaymentRequest.builder().amount(new BigDecimal("200.00")).requestKey("ar-pay-1").paymentMethod("BANK_TRANSFER").externalReference("BANK-1").build();var first=service.pay(2L,request);when(db.byRequest("ar-pay-1")).thenReturn(first);var retry=service.pay(2L,request);assertEquals(first.getId(),retry.getId());verify(tx,times(1)).insertTransaction(argThat((HotelTransactionRecord x)->"EXTERNAL_IN".equals(x.getDirection())&&"AR_PAYMENT".equals(x.getSourceType())&&x.getBusinessDate().equals(LocalDate.of(2026,9,23))));}
 @Test void creditLimitAndOverpaymentAreRejected(){var limited=ArAccount.builder().id(2L).status("ACTIVE").currency("CNY").creditLimit(new BigDecimal("1000.00")).build();when(folios.selectByIdForUpdate(3L)).thenReturn(Folio.builder().id(3L).currency("CNY").balanceAmount(new BigDecimal("200.00")).build());when(db.lockAccount(2L)).thenReturn(limited);when(db.outstanding(2L)).thenReturn(new BigDecimal("900.00"));when(financial.recalculateSummary(3L)).thenReturn(Folio.builder().id(3L).balanceAmount(new BigDecimal("200.00")).build());assertThrows(RuntimeException.class,()->service.transfer(2L,3L,TransferRequest.builder().amount(new BigDecimal("200.00")).requestKey("over-limit").build()));assertThrows(RuntimeException.class,()->service.pay(2L,PaymentRequest.builder().amount(new BigDecimal("1200.00")).requestKey("over-pay").paymentMethod("CASH").build()));verifyNoInteractions(tx);}
}
